#tianai-captcha-parent #tianai-captcha-box .loading{width:50px;height:50px;text-align:center;display:block;z-index:998;position:absolute;top:105px;left:126px;-moz-user-select:none;-webkit-user-select:none;-ms-user-select:none;user-select:none;background-image:url(data:image/gif;base64,);background-size:cover}
#tianai-captcha-parent #tianai-captcha-box #tianai-captcha{-webkit-transform-style:preserve-3d;transform-style:preserve-3d;will-change:transform;-webkit-transition-duration:.5s;transition-duration:.5s;-webkit-transition-timing-function:cubic-bezier(.36,.3,.42,1.5);transition-timing-function:cubic-bezier(.36,.3,.42,1.5);-webkit-transform:translateX(-300px);transform:translateX(-300px)}
#tianai-captcha-parent #tianai-captcha-bg-img{background-color:#fff;background-position:top;background-size:cover;z-index:-1;width:100%;height:100%;top:0;left:0;position:absolute;border-radius:6px}
