#tianai-captcha.tianai-captcha-rotate2 #tianai-captcha-slider-bg-degree-canvas{position:absolute;top:0;width:180px;height:180px;left:60px;border-radius:50%;-webkit-transform:rotate(0deg);transform:rotate(0deg)}
#tianai-captcha.tianai-captcha-scrape #tianai-captcha-scrape-tip-img{display:inline-block;height:19px;vertical-align:text-bottom}
#tianai-captcha.tianai-captcha-scrape .slider-img-div{height:100%;width:100%;position:absolute;background-color:#d8d8d8;-webkit-transform:translate(0);transform:translate(0);border-radius:0 5px 5px 0;-webkit-box-sizing:border-box;box-sizing:border-box;top:0;-webkit-box-shadow:-6 px 0 9px 0 #fff;box-shadow:-6 0 9px 0 px #fff}
#tianai-captcha.tianai-captcha-slider{z-index:999;position:absolute;left:0;top:0;-webkit-user-select:none;-moz-user-select:none;-ms-user-select:none;user-select:none}
