#tianai-captcha.tianai-captcha-slider .slider-move{height:34px;width:100%;margin:11px 0;position:relative}
#tianai-captcha.tianai-captcha-slider .slider-move-track{position:relative;height:32px;line-height:32px;text-align:center;background:#f5f5f5;color:#999;-webkit-transition:0s;transition:0s;font-size:14px;-webkit-box-sizing:content-box;box-sizing:content-box;border:1px solid #f5f5f5;border-radius:4px}
