#tianai-captcha.tianai-captcha-slider .slider-move{line-height:38px;font-size:14px;text-align:center;white-space:nowrap;color:#88949d;-moz-user-select:none;-webkit-user-select:none;-ms-user-select:none;user-select:none;-webkit-filter:opacity(.8);filter:opacity(.8)}
#tianai-captcha.tianai-captcha-slider .slider-move .slider-move-btn{-webkit-transform:translate(0);transform:translate(0);position:absolute;top:-6px;left:0;width:63px;height:45px;background-color:#fff;background-repeat:no-repeat;background-size:contain;border-radius:5px}
