#tianai-captcha.tianai-captcha-slider .tianai-captcha-curve-ball-div{position:absolute;left:0;top:0;width:16px;height:16px;border-radius:50%;background-color:#fff;border:1px solid rgba(73,72,72,.4705882353);display:none}
#tianai-captcha.tianai-captcha-disable .content{width:100%;height:180px;position:relative;overflow:hidden}
