#tianai-captcha.tianai-captcha-disable .content .bg-img-div #content-span{color:#fff;overflow:hidden;margin-top:132px;display:block;text-align:center}
#tianai-captcha.tianai-captcha-disable .slider-tip{width:100%;height:32px;line-height:24px;position:relative;text-align:center}
